item.content:encoded:
:root {
	--border-color: #dfdfdf;
}
.label-custom {
	font-weight: bold;
	color: var( --e-global-color-primary );
}
.form-custom {
	margin-top: 15px;
}
.elementor-widget-testimonial-carousel .swiper-slide {
	padding: 0 !important;
}
.swiper-pagination-bullet {
    background: #b7b7b7;
}
.floating-whatsapp {
	position:fixed;
	width:50px;
	height:50px;
	bottom:15px;
	right:15px;
	border-radius:50px;
  z-index:100;
	display:flex;
	justify-content: center;
	align-items: center;
	transition: all 0.3s ease;
}
ul {
    margin-block-start: 0;
    margin-block-end: 0;
    margin-inline-start: 0px;
    margin-inline-end: 0px;
    padding-inline-start: 00px;
}
ul li {
	  list-style-type: none;
}
.button-standard a, .button-standard-reverse a {
	position: relative !important;
	transition: all 0.3s ease;
	overflow: hidden;
}
.button-standard a:hover {
	color: white !important;
}
.button-standard-reverse a:hover {
	color: var(--e-global-color-primary) !important;
}
.button-standard a:hover:before, .button-standard-reverse a:hover:before {
	    width: 50%;
    	opacity: 1;
}
.button-standard a span span, .button-standard-reverse a span span{
	z-index: 10
}
.button-standard a:hover:after, .button-standard-reverse a:hover:after {
	    width: 50%;
    	opacity: 1;
}
.button-standard a:before{
	   position: absolute;
    content: "";
    left: 0;
    top: 0;
    width: 0;
    height: 100%;
    opacity: 0;
    z-index: 5;
    transition: 0.5s all ease;
    background-color: var(--e-global-color-primary);
}
.button-standard-reverse a:before{
	   position: absolute;
    content: "";
    left: 0;
    top: 0;
    width: 0;
    height: 100%;
    opacity: 0;
    z-index: 5;
    transition: 0.5s all ease;
    background-color: white;
}
.button-standard a:after {
	  position: absolute;
    content: "";
    right: 0;
    top: 0;
    width: 0;
    height: 100%;
    opacity: 0;
    z-index: 5;
    transition: 0.5s all ease;
    background-color: var(--e-global-color-primary);
}
.button-standard-reverse a:after {
	  position: absolute;
    content: "";
    right: 0;
    top: 0;
    width: 0;
    height: 100%;
    opacity: 0;
    z-index: 5;
    transition: 0.5s all ease;
    background-color: white;
}
.btn-send-form {
	background: var( --e-global-color-primary ) !important;
	color: white !important;
}
.btn-send-form:hover {
	background: #042f68 !important;
}

.header-primary.sticky {
	z-index: 10000;
	background-color: white !important;
	border-bottom: 1px solid #dfdfdf !important;
	box-shadow: rgba(100, 100, 111, 0.2) 0px 7px 29px 0px !important;
}
@media (max-width: 768px) {
	.swiper-pagination-bullets {
		bottom: 10px !important;
		flex-direction: row !important;
	}
}
@media (min-width: 481px and max-width: 768px) {
 .header-primary.active {
	display: none !important;
}
	.swiper-pagination-bullets {
		bottom: 10px !important
	}
}

 @media (min-width: 769px) {

.header-fixed.active {
	display: flex !important;
		transition: all .2s linear!important;
	-webkit-transition: all .2s linear!important;
	-moz-transition: all .2s linear!important;
}
}

/** Start Block Kit CSS: 142-3-a175df65179b9ef6a5ca9f1b2c0202b9 **/

.envato-block__preview{
	overflow: visible;
}
/* shrinking header section */

.shrinker {
	background: transparent;
	transition: all .2s linear!important;
	-webkit-transition: all .2s linear!important;
	-moz-transition: all .2s linear!important;
}

.shrinker.elementor-sticky--effects {
	background: #fff;
	padding-top: 2px!important;
	padding-bottom: 2px!important;
	box-shadow: 0px 6px 30px -4px rgba(0,0,0,.05);
	transition: all .2s linear!important;
	-webkit-transition: all .2s linear!important;
	-moz-transition: all .2s linear!important;
}
/* Border Radius */
.envato-kit-139-accordion .elementor-widget-container{
	border-radius: 10px !important;
}
.envato-kit-139-map iframe,
.envato-kit-139-slider .slick-slide,
.envato-kit-139-flipbox .elementor-flip-box div{
		border-radius: 10px !important;

}


/** End Block Kit CSS: 142-3-a175df65179b9ef6a5ca9f1b2c0202b9 **/



/** Start Block Kit CSS: 136-3-fc37602abad173a9d9d95d89bbe6bb80 **/

.envato-block__preview{overflow: visible !important;}

/** End Block Kit CSS: 136-3-fc37602abad173a9d9d95d89bbe6bb80 **/

